"use client";

import { useState } from "react";
import Link from "next/link";

const options = ["Friendships", "My year", "Relationship", "Pets", "Baby / family", "Travel / life", "Home", "Family history", "Startup", "Creator journey"];

export default function OnboardingPage() {
  const [selected, setSelected] = useState<string[]>([]);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  async function finish() {
    setLoading(true); setMessage("");
    try {
      const response = await fetch("/api/profile", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ interests: selected, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone, locale: navigator.language, onboardingCompleted: true }) });
      const data = await response.json() as { error?: string };
      if (!response.ok) throw new Error(data.error ?? "Could not save onboarding.");
      window.location.assign("/app");
    } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Could not save onboarding."); }
    finally { setLoading(false); }
  }
  return <main className="saas-onboarding"><section><span className="saas-kicker">WELCOME TO YOUR MEMORY OS</span><h1>What do you want to preserve?</h1><p>This only personalizes your starting shelf. Every story product remains available.</p><div className="saas-interest-grid">{options.map((option) => <button key={option} type="button" className={selected.includes(option) ? "selected" : ""} onClick={() => setSelected((current) => current.includes(option) ? current.filter((item) => item !== option) : [...current, option])}>{option}</button>)}</div><div className="premium-actions"><button className="btn btn-primary" onClick={finish} disabled={loading}>{loading ? "Saving…" : "Enter my story space"}</button><Link className="btn btn-soft" href="/app">Skip for now</Link></div>{message ? <div className="notice" role="status">{message}</div> : null}</section></main>;
}

import { Footer } from "@/components/Footer";
import { Header } from "@/components/Header";
import { HowItFeelsSection, LandingHero, PrivacyPromiseStrip, StoryPreviewSection } from "@/components/MemoryCinemaLanding";

export default function Home() {
  return <>
    <Header />
    <main>
      <LandingHero />
      <PrivacyPromiseStrip />
      <StoryPreviewSection />
      <HowItFeelsSection />
      <section className="shell section mc-privacy-feature">
        <div className="mc-section-heading"><span className="mc-eyebrow dark"><i /> Privacy is part of the interface</span><h2>Your group chat is not our training data.</h2><p>ThreadTales analyzes raw exports locally by default. Public links contain derived story facts, and cloud/AI features are explicit rather than hidden.</p></div>
        <div className="mc-privacy-receipt"><div><span>raw_chat.txt</span><b>→</b><span>browser memory</span><b>→</b><span>derived story</span><b>→</b><span>you choose what leaves</span></div><dl><div><dt>Raw chat server upload</dt><dd>None by default</dd></div><div><dt>Account required</dt><dd>No</dd></div><div><dt>Public link payload</dt><dd>Derived facts only</dd></div><div><dt>AI</dt><dd>Optional / bounded</dd></div></dl></div>
      </section>
    </main>
    <Footer />
  </>;
}

import { Footer } from "@/components/Footer";
import { Header } from "@/components/Header";
import { PremiumRecovery } from "@/components/PremiumRecovery";

export const metadata = {
  title: "ThreadTales Premium — Purchase verification",
  description: "Verify a ThreadTales Premium purchase and recover the signed export entitlement.",
};

export default async function PremiumSuccessPage({ searchParams }: { searchParams: Promise<{ session_id?: string }> }) {
  const { session_id: sessionId } = await searchParams;
  return <><Header/><main className="shell hero">{sessionId ? <PremiumRecovery sessionId={sessionId}/> : <div className="premium-recovery"><span className="kicker">Purchase verification</span><h1>Missing Checkout Session.</h1><p>Return to ThreadTales and start checkout again. Premium is never unlocked from an unverified success flag.</p></div>}</main><Footer/></>;
}

import { Header } from "@/components/Header";
import { Footer } from "@/components/Footer";
export default function Privacy(){return <><Header/><main className="shell section"><span className="kicker">Privacy model · V1</span><h2>We designed the cheap architecture to also be the private architecture.</h2><p className="section-copy">ThreadTales V1 reads your text export using the browser File API. Parsing and statistical analysis happen in local browser memory. The app does not send the raw file or message text to an API, database, object store, analytics pipeline, or AI model.</p><div className="grid3"><div className="feature"><div className="feature-icon">🧠</div><h3>Local processing</h3><p>Your raw chat exists only on the device and in the browser tab while you analyze it.</p></div><div className="feature"><div className="feature-icon">🔗</div><h3>Stat-only sharing</h3><p>Public links encode a compact snapshot of derived numbers. Top words are opt-in because even aggregates can be personal.</p></div><div className="feature"><div className="feature-icon">🗑️</div><h3>Nothing to delete</h3><p>There is no central V1 chat-history database. Closing the tab clears the in-memory raw content.</p></div></div><div className="privacy-banner" style={{marginTop:34}}><div><h2>What changes later?</h2><p>If we add accounts, saved stories, AI-written chapters, or paid cloud storage, those features should be explicit opt-ins with separate retention controls. They should not silently weaken the default privacy model.</p></div><div className="code-pill">default = local-only<br/>public = derived-only<br/>raw text sharing = never automatic<br/>AI enrichment = future opt-in</div></div></main><Footer/></>}

import Link from "next/link";
import { notFound } from "next/navigation";
import { Footer } from "@/components/Footer";
import { Header } from "@/components/Header";
import { MyYearCalendarImport } from "@/components/MyYearCalendarImport";
import { MyYearBuilder } from "@/components/MyYearBuilder";
import { PetLifeBuilder } from "@/components/PetLifeBuilder";
import { PetLifeSharedMemoryPanel } from "@/components/PetLifeSharedMemoryPanel";
import { WorldBuilder } from "@/components/WorldBuilder";
import { getProduct, products } from "@/lib/products";
import { isWorldSlug } from "@/products/worlds/config";

export function generateStaticParams() { return products.map((product) => ({ slug: product.slug })); }

export default async function ProductPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const product = getProduct(slug);
  if (!product) notFound();
  return <><Header/><main className="mc-product-page"><section className="shell hero mc-product-hero"><span className="mc-eyebrow dark"><i /> Live product</span><div className="mc-product-emoji">{product.emoji}</div><h1>{product.name}</h1><p>{product.tagline}</p><div className="hero-actions">{product.slug === "friendship" ? <Link className="btn btn-primary" href="/create">Create one →</Link> : <a className="btn btn-primary" href={`#${product.slug}-builder`}>Open your world →</a>}</div></section>{product.slug === "myyear" ? <section id="myyear-builder" className="shell section" style={{paddingTop:20}}><MyYearBuilder/><MyYearCalendarImport/></section> : null}{product.slug === "petlife" ? <section id="petlife-builder" className="shell section" style={{paddingTop:20}}><PetLifeBuilder/><PetLifeSharedMemoryPanel/></section> : null}{isWorldSlug(product.slug) ? <section className="shell section" style={{paddingTop:20}}><WorldBuilder slug={product.slug}/></section> : null}<section className="shell section" style={{paddingTop:20}}><div className="mc-product-facts"><article><small>Who it is for</small><strong>{product.audience}</strong></article><article><small>Input</small><strong>{product.input}</strong></article><article><small>Output</small><strong>{product.output}</strong></article><article><small>Business model</small><strong>{product.businessModel}</strong></article><article><small>Persistence</small><strong>{product.needsPersistence ? "Optional account/cloud layer; local product works first" : "Local-first"}</strong></article><article><small>Privacy</small><strong>Private by default; sharing is selected and derived-only</strong></article></div></section></main><Footer/></>;
}

import Link from "next/link";
import { Footer } from "@/components/Footer";
import { Header } from "@/components/Header";
import { products } from "@/lib/products";

function stageLabel() { return "Live"; }

export default function ProductsPage() {
  return <><Header/><main className="mc-product-page"><section className="shell mc-products-hero"><span className="mc-eyebrow dark"><i /> Personal Story Platform</span><h1>Your memories have more than one shape.</h1><p className="section-copy">Ten usable, private-by-default story products. Every one starts with manual or local file input, creates a deterministic world, and offers editing, reset, export and a selected share-safe summary.</p></section><section className="shell section" style={{paddingTop:30}}><div className="mc-products-grid">{products.map((product) => <Link className="mc-product-card" href={`/products/${product.slug}`} key={product.slug}><span className="mc-product-stage live">{stageLabel()}</span><div className="feature-icon">{product.emoji}</div><h3>{product.name}</h3><p>{product.tagline}</p><div className="mc-product-meta"><strong>For:</strong> {product.audience}<br/><strong>Input:</strong> {product.input}<br/><strong>Output:</strong> {product.output}<br/><strong>Model:</strong> {product.businessModel}<br/><strong>Persistence:</strong> {product.needsPersistence ? "Local first; optional cloud layer" : "Local-first"}<br/><strong>Foundation:</strong> shared story, privacy, export and entitlement primitives</div></Link>)}</div></section></main><Footer/></>;
}

